import type jsPDF from "jspdf";

/**
 * Header PDF standar CRM & Sales - dipakai SEMUA dokumen PDF supaya tampilan atas
 * seragam dengan PDF Penawaran: blok navy + garis oranye, logo MSDC di kiri,
 * judul di tengah, label "CRM & SALES / MSDC Surabaya / <jenis dokumen>" di kanan.
 *
 * Setelah dipanggil, font/warna teks diubah - caller sebaiknya set ulang
 * font & warna untuk isi dokumen.
 */
export const MSDC_PDF_LOGO =
  "data:image/png;base64,";

const NAVY: [number, number, number] = [9, 39, 71];
const ORANGE: [number, number, number] = [247, 171, 0];

export function drawMsdcPdfHeader(
  doc: jsPDF,
  opts: {
    /** Judul besar di tengah. */
    title: string;
    /** Teks kecil di bawah judul (opsional). */
    subtitle?: string;
    /** Baris ketiga di kanan, mis. "Dokumen Kontrak" / "Laporan Prospek". */
    docLabel: string;
    /** Margin kiri-kanan (mm). Portrait: 14, landscape: 10. */
    marginX?: number;
  },
): void {
  const pageWidth = doc.internal.pageSize.getWidth();
  const marginX = opts.marginX ?? 14;

  doc.setFillColor(NAVY[0], NAVY[1], NAVY[2]);
  doc.rect(0, 0, pageWidth, 35, "F");

  doc.setFillColor(ORANGE[0], ORANGE[1], ORANGE[2]);
  doc.rect(0, 35, pageWidth, 2.2, "F");

  try {
    doc.addImage(MSDC_PDF_LOGO, "PNG", marginX, 8.5, 39, 15.5, undefined, "FAST");
  } catch {
    doc.setTextColor(255, 255, 255);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(13);
    doc.text("MSDC", marginX, 15);
    doc.setFontSize(6);
    doc.text("SURABAYA", marginX, 20);
  }

  doc.setTextColor(255, 255, 255);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12.5);
  doc.text(opts.title, pageWidth / 2, 14.5, { align: "center", maxWidth: pageWidth - 130 });

  if (opts.subtitle) {
    doc.setTextColor(203, 213, 225);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(6.6);
    doc.text(opts.subtitle, pageWidth / 2, 20.2, { align: "center", maxWidth: pageWidth - 130 });
  }

  doc.setTextColor(255, 255, 255);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(7.2);
  doc.text("CRM & SALES", pageWidth - marginX, 13.5, { align: "right" });

  doc.setTextColor(203, 213, 225);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(6.1);
  doc.text("MSDC Surabaya", pageWidth - marginX, 18.4, { align: "right" });
  doc.text(opts.docLabel, pageWidth - marginX, 22.6, { align: "right" });
}
